"""Verify checksum manifests from actual files, including streaming-sized input."""
import hashlib
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

from backend.deploy.vps import bundle_helpers
from backend.deploy.vps.bundle_helpers import write_checksums

class WriteChecksumsTest(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix="cftracker-checksum-test-")
        self.addCleanup(temporary.cleanup)
        self.directory = Path(temporary.name)

    # Generated by Codex and not thoroughly checked for correctness.
    def test_cli_hashes_large_files_sorts_names_and_excludes_checksum_manifest(self):
        content = b"a" * (1024 * 1024) + b"bc"
        (self.directory / "images.tar").write_bytes(content)
        (self.directory / "compose.yml").write_bytes(b"abc")
        manifest = self.directory / "SHA256SUMS"
        manifest.write_text("stale checksums\n")
        subprocess.run([
            sys.executable, str(Path(bundle_helpers.__file__)),
            "checksums", str(self.directory),
        ], check=True, capture_output=True, text=True)
        # hashlib supplies an independent whole-buffer oracle for the streaming
        # writer. The subject is file traversal, streaming and manifest output.
        self.assertEqual(manifest.read_text(),
                         "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad  compose.yml\n"
                         + hashlib.sha256(content).hexdigest() + "  images.tar\n")
        self.assertEqual((self.directory / "images.tar").read_bytes(), content)
        write_checksums(self.directory)
        self.assertEqual(len(manifest.read_text().splitlines()), 2)

    # Generated by Codex and not thoroughly checked for correctness.
    def test_empty_file_gets_the_standard_empty_sha256_digest(self):
        (self.directory / "empty.tar").write_bytes(b"")
        write_checksums(self.directory)
        self.assertEqual((self.directory / "SHA256SUMS").read_text(),
                         "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855  empty.tar\n")

    # Generated by Codex and not thoroughly checked for correctness.
    def test_unreadable_directory_entry_does_not_record_a_successful_digest(self):
        (self.directory / "a-directory").mkdir()
        with self.assertRaises(IsADirectoryError):
            write_checksums(self.directory)
        self.assertEqual((self.directory / "SHA256SUMS").read_text(), "")
